var robots = RobotsFile.Parse("""
    User-agent: *
    Disallow: /private/
    Allow: /public/

    Sitemap: https://example.com/sitemap.xml
    """);

bool allowed = robots.IsAllowed("Googlebot", "/public/page");

foreach (var error in robots.ParseErrors)
    Console.WriteLine(error);
